pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deposit 1 ether to the contract (via fallback)
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        (bool successDeposit,) = address(c).call{value: 1 ether}("");
        require(successDeposit, "deposit failed");

        // The owner (this contract in Foundry test) calls withdrawAll()
        // In the reference contract, this succeeds and transfers balance to msg.sender
        // In the buggy contract, this calls sendMoney(owner, address(this).balance) which reverts
        // because the fallback function increments depositsCount but does not have receive() to accept Ether
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract succeeds (ok == true), the buggy contract reverts (ok == false)
        assertTrue(ok, "withdrawAll should succeed");
    }
}

