pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple contract that accepts ether without reverting
        address target = address(new EtherReceiver());

        // Fund the C contract with some ether
        vm.deal(address(c), 1 ether);

        // Call sendMoney from the owner
        vm.prank(address(this));
        c.sendMoney(target, 0.5 ether);

        // In the reference (correct version), if the call succeeds, the condition !_s is false, so no revert; fallback is invoked, depositsCount becomes 1.
        // In the buggy version, if the call succeeds, the condition _s is true, so it reverts; fallback is not invoked, depositsCount stays 0.
        // Assert that depositsCount is 1 (reference holds, bug breaks).
        assertTrue(c.depositsCount() == 1);
    }
}

