import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: non-owner (address(0x1)) calls sendMoney with 1 wei to a reverting target
        address nonOwner = address(0x1);
        address revertingTarget = address(0xdead);
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        // For reference P, this reverts (onlyOwner); for mutant M, it proceeds (no modifier)
        bool ok;
        try c.sendMoney{value: 1 wei}(revertingTarget, 1 wei) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference (correct), the call reverts => ok == false
        // In mutant (buggy), the call reverts internally (because target reverts) but sendMoney succeeds => ok == true, and depositsCount becomes 1
        // Assert the reference behavior: ok == false
        assertTrue(!ok);
    }
}

