        // Deploy a contract that reverts on receive
        Reverter reverter = new Reverter();

        // First, successful sendMoney from owner to owner
        vm.deal(address(c), 2 ether);
        vm.prank(c.owner());
        c.sendMoney(c.owner(), 1 wei);

        // Then, failing sendMoney to the reverter contract
        vm.prank(c.owner());
        c.sendMoney(address(reverter), 1 wei);

        // Assert: reference has depositsCount = 1, buggy has 2
